noncompliant.code:
from typing import List

class Person:
    pass

class Dog:
    pass

people: List[Person] = [Dog()]  # Type mismatch: Dog instance in List[Person]

compliant.code:
from typing import List

class Person:
    pass

class Student(Person):
    pass

people: List[Person] = [Student()]  # Correct: Student is subclass of Person
